"use strict";
GUIDE_DATA_VI.sections.push({"id":"g69","part":7,"title":"Phân loại và xử lý dữ liệu (Data Classification and Handling)","blocks":[{"level":1,"text":"4 danh mục dữ liệu chính"},{"level":2,"text":"Dữ liệu công khai (Public Data)"},{"level":2,"text":"Ít nhạy cảm nhất và ai cũng có thể tiếp cận"},{"level":2,"text":"Dữ liệu nội bộ (Internal Data)"},{"level":2,"text":"Nhân viên trong công ty có thể tiếp cận và không công khai ra bên ngoài"},{"level":2,"text":"Dữ liệu mật (Confidential Data)"},{"level":2,"text":"Rất nhạy cảm và quyền truy cập bị hạn chế"},{"level":2,"text":"Bao gồm thông tin cần thiết để nhân viên thực hiện nhiệm vụ"},{"level":2,"text":"Dữ liệu hạn chế (Restricted Data)"},{"level":2,"text":"Loại dữ liệu nhạy cảm nhất, trong đó quyền truy cập bị hạn chế và chỉ được cấp trên cơ sở cần-biết (need-to-know) với lý do kinh doanh chặt chẽ"},{"level":1,"text":"Thông tin nhận dạng cá nhân (Personally Identifiable Information - PII)"},{"level":2,"text":"Dữ liệu có thể dùng để nhận dạng một cá nhân"},{"level":2,"text":"Số An sinh xã hội (Social Security Numbers)"},{"level":2,"text":"Địa chỉ email (Email Addresses)"},{"level":2,"text":"Mật khẩu (Passwords)"},{"level":2,"text":"Số hộ chiếu (Passport Numbers)"},{"level":1,"text":"Thông tin sức khỏe cá nhân (Personal Health Information - PHI)"},{"level":2,"text":"Được luật liên bang Mỹ bảo vệ theo quy định HIPAA, yêu cầu các tổ chức bảo vệ chống truy cập và tiết lộ trái phép thông tin sức khỏe nhạy cảm"},{"level":2,"text":"PHI là sự kết hợp của PII và thông tin sức khỏe"},{"level":2,"text":"PII"},{"level":2,"text":"Danh tính của một người"},{"level":2,"text":"PHI"},{"level":2,"text":"Thông tin sức khỏe"},{"level":1,"text":"Quy định chung về bảo vệ dữ liệu (General Data Protection Regulation - GDPR)"},{"level":2,"text":"Luật bảo mật và an toàn dữ liệu của Liên minh châu Âu (EU) bao gồm 11 chương quy định và được coi là luật bảo mật nghiêm ngặt nhất"},{"level":1,"text":"Các luật bảo mật dữ liệu bảo vệ người tiêu dùng trong phạm vi quyền tài phán của họ"},{"level":1,"text":"Việc không tuân thủ các quy định có hậu quả tiêu cực cho cả cá nhân và công ty"},{"level":1,"text":"Sở hữu trí tuệ (Intellectual Property - IP)"},{"level":2,"text":"Các sáng tạo của trí óc đóng vai trò là tài sản trong kinh doanh"},{"level":2,"text":"4 loại tài sản sở hữu trí tuệ"},{"level":2,"text":"Bằng sáng chế (Patents)"},{"level":2,"text":"Bản quyền (Copyrights)"},{"level":2,"text":"Nhãn hiệu (Trademarks)"},{"level":2,"text":"Bí mật thương mại (Trade Secrets)"},{"level":2,"text":"Một danh mục độc đáo của sở hữu trí tuệ có thể mang lại lợi thế cạnh tranh cho công ty"},{"level":1,"text":"Hạn chế về thương hiệu (Branding Restrictions)"},{"level":2,"text":"Một công ty có thể có logo đã được đăng ký nhãn hiệu và được phép dùng trên tài liệu và sản phẩm của mình"},{"level":2,"text":"Công ty có thể giới hạn vị trí logo trên một trang và loại tài liệu nào được phép bao gồm nó"},{"level":2,"text":"Công ty có thể tạo các mẫu (template) cho các loại tài liệu khác nhau"}]},{"id":"g70","part":7,"title":"An ninh vận hành (Operational Security)","blocks":[{"level":1,"text":"An ninh số và an ninh vận hành là yếu tố tối quan trọng để bảo vệ thông tin nhạy cảm"},{"level":1,"text":"Điều quan trọng là cấp quyền truy cập cho thành viên nhóm dự án và các bên liên quan với đặc quyền tối thiểu cần thiết"},{"level":1,"text":"Mức độ truy cập của các sản phẩm được thêm vào thiết kế giải pháp phải đáp ứng các yêu cầu"},{"level":1,"text":"Thiết lập chính sách truy cập từ xa (remote access policy) quy định ai có thể kết nối vào mạng và bằng cách nào"},{"level":1,"text":"Sử dụng xác thực đa yếu tố (multi-factor authentication) để bảo vệ hệ thống"},{"level":1,"text":"Xác thực đa yếu tố (Multi-Factor Authentication - MFA)"},{"level":2,"text":"Tăng cường bảo mật bằng cách yêu cầu người dùng cung cấp ít nhất hai bằng chứng để truy cập một hệ thống hoặc tài nguyên từ xa"},{"level":2,"text":"Quy trình bao gồm hai hoặc nhiều thông tin xác thực, thuộc ba loại:"},{"level":2,"text":"Thứ bạn biết (Something you know)"},{"level":2,"text":"Thứ bạn có (Something you have)"},{"level":2,"text":"Thứ bạn là (Something you are)"},{"level":2,"text":"MFA thường được các công ty dùng để truy cập mạng, trong đó nhân viên phải nhập mật khẩu và quét thẻ thông minh để đăng nhập vào máy tính tại nơi làm việc"},{"level":1,"text":"An ninh vận hành (Operational Security - OPSEC) đưa con người và môi trường vật lý vào phương trình bảo mật"},{"level":2,"text":"Phương tiện lưu trữ di động (Removable Media)"},{"level":2,"text":"Phương tiện lưu trữ di động, như ổ USB, mang đến cho người dùng cách thuận tiện để lưu trữ và chuyển file giữa các máy tính"},{"level":2,"text":"Chúng cũng gây ra rủi ro bảo mật đáng kể vì có thể dễ dàng bị sao chép hoặc mang đi"},{"level":2,"text":"Để giảm thiểu rủi ro này, các công ty có thể hạn chế việc sử dụng phương tiện lưu trữ di động và triển khai các chính sách bảo mật như quản lý USB (USB management) ghi lại mọi kết nối và có thể chặn việc sử dụng phương tiện lưu trữ di động"},{"level":2,"text":"Thiết bị di động (Mobile Devices)"},{"level":2,"text":"Thiết bị di động ngày càng trở thành cách phổ biến để nhân viên truy cập các ứng dụng và dữ liệu của công ty"},{"level":2,"text":"Nó tạo thêm rủi ro bảo mật vì tài sản công ty có thể được truy cập từ nhiều địa điểm khác nhau"},{"level":2,"text":"Để giải quyết vấn đề này, các công ty có thể cấp thiết bị của công ty và yêu cầu sử dụng phần mềm quản lý thiết bị di động (mobile device management - MDM), cho phép bộ phận CNTT giám sát và xóa từ xa các thiết bị bị xâm nhập"},{"level":2,"text":"Quyền ra vào cơ sở (Facility Access)"},{"level":2,"text":"Việc truy cập trái phép vào cơ sở của công ty có thể dẫn đến trộm cắp tài sản hoặc xâm nhập mạng"},{"level":2,"text":"Để ngăn chặn điều này, các công ty giới hạn quyền ra vào cơ sở chỉ cho người dùng được ủy quyền"},{"level":2,"text":"Điều này giúp đảm bảo tài sản công ty, bao gồm máy tính, thiết bị di động và tài liệu, được bảo vệ và an toàn"},{"level":2,"text":"Sàng lọc lý lịch (Background Screening)"},{"level":2,"text":"Nếu dự án của bạn liên quan đến việc xử lý thông tin về quốc phòng hoặc đối ngoại, nó được coi là thông tin an ninh quốc gia tại Hoa Kỳ"},{"level":2,"text":"Việc truy cập thông tin này bị hạn chế nghiêm ngặt, và nó nên nhận mức phân loại nhạy cảm cao nhất"},{"level":2,"text":"Thông tin an ninh quốc gia hoặc yêu cầu cấp phép (National Security Information or Clearance Requirements)"},{"level":1,"text":"Các cá nhân cần truy cập thông tin này phải vượt qua kiểm tra lý lịch và tín dụng để được cấp phép, tương tự như một cuộc kiểm tra lý lịch chuyên sâu"},{"level":1,"text":"4 cấp độ cấp phép (Clearance Levels)"},{"level":2,"text":"Mật (Confidential)"},{"level":2,"text":"Tối mật (Secret)"},{"level":2,"text":"Tuyệt mật (Top Secret)"},{"level":2,"text":"Thông tin phân chia nhạy cảm (Sensitive Compartmented Information - SCI)"},{"level":1,"text":"Yêu cầu cấp phép của dự án được quyết định bởi bản chất của thông tin đang được xử lý. Quản lý nguồn lực (Managing Resources)"}]},{"id":"g71","part":8,"title":"Quản lý nguồn lực (Managing Resources)","blocks":[{"level":1,"text":"Quản lý nguồn lực (Resource management) là một khía cạnh then chốt của quản lý dự án và bao trùm từ giai đoạn Planning đến giai đoạn Closing của dự án"},{"level":1,"text":"PM có trách nhiệm đóng góp vào sự phát triển chuyên môn của các thành viên trong nhóm"},{"level":1,"text":"Nguồn lực, cả vật chất và con người, đều trải qua vòng đời bốn giai đoạn"},{"level":2,"text":"Mua sắm (Acquisition)"},{"level":2,"text":"Bảo trì (Maintenance)"},{"level":2,"text":"Cải thiện (Improvement)"},{"level":2,"text":"Loại bỏ (Retirement)"},{"level":1,"text":"Lập kế hoạch kế nhiệm (Succession Planning)"},{"level":2,"text":"Rất quan trọng để xác định người thay thế tiềm năng cho các vai trò trọng yếu, thúc đẩy phát triển nghề nghiệp, và đảm bảo chuyển giao kiến thức và khả năng phục hồi trong tổ chức"},{"level":1,"text":"Các nhà quản lý dự án đóng vai trò then chốt trong việc huy động các nguồn lực cần thiết để hoàn thành dự án thành công"},{"level":2,"text":"Các nguồn lực này bao gồm hỗ trợ tài chính và tài sản hữu hình"},{"level":1,"text":"Nguồn lực không đủ có thể dẫn đến trải nghiệm căng thẳng cho nhóm và làm tăng khả năng thất bại của dự án"},{"level":1,"text":"Bằng cách tuân theo quy trình đánh giá nhu cầu có cấu trúc, các nhà quản lý dự án có thể tạo ra một kế hoạch nguồn lực cân bằng đảm bảo thành công của dự án"},{"level":1,"text":"Phân tích khoảng trống (Gap analysis) là một cách tiếp cận linh hoạt nhằm điều tra nguyên nhân của các khoảng trống và các giải pháp tiềm năng, sử dụng các công cụ như biểu đồ xương cá (fishbone diagram), ma trận kỹ năng (skills matrix) và biểu đồ tần suất (histogram)"},{"level":1,"text":"Quản lý nguồn lực trong quản lý dự án bao gồm năm bước chính"},{"level":2,"text":"Ước tính các nguồn lực cần thiết"},{"level":2,"text":"Bảo đảm nguồn lực"},{"level":2,"text":"Đào tạo thành viên nhóm"},{"level":2,"text":"Phân bổ nguồn lực cho các công việc"},{"level":2,"text":"Giám sát và điều chỉnh nguồn lực"}]},{"id":"g72","part":8,"title":"Các loại nguồn lực (Types of Resources)","blocks":[{"level":1,"text":"Các nhà quản lý dự án cần huy động, quản lý và loại bỏ nguồn lực"},{"level":1,"text":"Điều thiết yếu là phải hiểu sự khác biệt giữa nguồn lực con người, nguồn lực vật chất và nguồn lực vốn trong suốt quá trình quản lý dự án"},{"level":1,"text":"Nguồn lực con người (Human resources) bao gồm thời gian, kỹ năng và kiến thức của các cá nhân được áp dụng vào các công việc của dự án"},{"level":1,"text":"Nguồn lực vật chất (Physical resources) là các hàng hóa cần thiết để hỗ trợ một dự án"},{"level":2,"text":"Thiết bị (Equipment)"},{"level":2,"text":"Phần mềm (Software)"},{"level":2,"text":"Văn phòng phẩm (Office Supplies)"},{"level":2,"text":"Không gian làm việc (Workspaces)"},{"level":2,"text":"Tòa nhà (Buildings)"},{"level":2,"text":"Phương tiện (Vehicles)"},{"level":1,"text":"Tiền được gọi là nguồn lực vốn (capital resources), bao gồm nguồn tài trợ cần thiết để thực hiện một dự án, bao gồm ngân sách nhóm và dự án cùng các khả năng đầu tư dài hạn"},{"level":1,"text":"Quản lý ngân sách là yếu tố then chốt đối với quản lý dự án"}]},{"id":"g73","part":8,"title":"Nguồn cung và phân bổ nguồn lực (Resource Sourcing and Allocation)","blocks":[{"level":1,"text":"Nguồn gốc của nguồn lực được xác định bởi phương thức huy động nguồn lực (sourcing method)"},{"level":1,"text":"Nội bộ (Internal) là nguồn lực nằm trong sở hữu của công ty hoặc sẽ được công ty mua sắm"},{"level":2,"text":"Nguồn lực nội bộ ít sẵn có hơn nhưng rẻ hơn so với nguồn lực bên ngoài"},{"level":1,"text":"Bên ngoài (External) là nguồn lực mà công ty không có và không có ý định mua bên ngoài phạm vi dự án"},{"level":2,"text":"Nguồn lực bên ngoài sẵn có hơn nhưng đắt hơn"},{"level":1,"text":"Việc lên lịch cho nguồn lực nội bộ có thể khó khăn vì chúng thường là các dịch vụ dùng chung"},{"level":1,"text":"Việc đánh giá nhà cung cấp từ sớm trong quy trình mua sắm có thể tiết kiệm thời gian và công sức"},{"level":1,"text":"Các dự án có mức độ ưu tiên cao có nhiều khả năng nhận được nguồn lực nội bộ theo lịch trình mong muốn hơn, nhưng chúng không kiểm soát được mọi sự phân bổ nguồn lực"},{"level":1,"text":"Các nguồn lực cực kỳ quan trọng có nhiều khả năng cần huy động từ bên ngoài khi không có lựa chọn nội bộ"},{"level":1,"text":"Nếu một dự án cần nguồn lực bên ngoài, cần phải xây dựng một kế hoạch mua sắm (procurement plan)"},{"level":2,"text":"Trong các giai đoạn lập kế hoạch ban đầu, hãy tiến hành đánh giá nhu cầu sơ bộ và tạo một kế hoạch mua sắm cấp cao"},{"level":2,"text":"Đánh giá nhu cầu (Needs Assessment)"},{"level":2,"text":"Quy trình có cấu trúc để xác định các hàng hóa và dịch vụ cần thiết để giải quyết vấn đề của dự án"},{"level":2,"text":"Kế hoạch mua sắm (Procurement Plan)"},{"level":2,"text":"Đóng vai trò là cơ sở kinh doanh (business case) cho việc sử dụng nguồn lực bên ngoài và phác thảo chiến lược tìm kiếm và quản lý nhà cung cấp"},{"level":2,"text":"Kế hoạch sơ bộ (Preliminary Plan)"},{"level":2,"text":"Có thể ít chi tiết hơn, nhưng sẽ tiếp tục được hoàn thiện trong suốt dự án"},{"level":1,"text":"Kế hoạch mua sắm có thể bao gồm các chi tiết sau:"},{"level":2,"text":"Tổng quan về các hàng hóa hoặc dịch vụ cần thiết"},{"level":2,"text":"Ngày giao hàng và triển khai"},{"level":2,"text":"Các ngày quan trọng (Critical dates)"},{"level":2,"text":"Phân tích tác động tài chính và rủi ro của việc mua sắm các nguồn lực này"},{"level":2,"text":"Các loại hợp đồng (Contract types)"},{"level":2,"text":"Phương pháp đánh giá (Evaluation methods)"},{"level":2,"text":"Các chỉ số hiệu suất nhà cung cấp (Vendor performance metrics)"},{"level":2,"text":"Các lựa chọn nhà cung cấp sẵn có"},{"level":2,"text":"Phân tích tài chính chi tiết"},{"level":1,"text":"Việc xây dựng kế hoạch mua sắm có thể cải thiện kết quả của dự án"},{"level":1,"text":"Mọi nguồn lực đều hoặc là chuyên dụng (dedicated) hoặc là dùng chung (shared), và phương thức phân bổ mô tả cách thời gian hoặc công suất của một nguồn lực được dùng trong một dự án"},{"level":2,"text":"Một nguồn lực chuyên dụng sẽ không đảm bảo công suất tối đa"},{"level":2,"text":"Nguồn lực chuyên dụng hữu ích khi dự án cần các kỹ năng hoặc thiết bị chuyên biệt"},{"level":2,"text":"Nguồn lực dùng chung là lựa chọn tốt hơn khi mức độ kỹ năng yêu cầu thấp hơn hoặc khi nguồn lực khan hiếm"}]},{"id":"g74","part":8,"title":"Tính toán công suất nguồn lực dùng chung (Calculating Shared Resource Capacity)","blocks":[{"level":1,"text":"Công suất của nguồn lực dùng chung (Shared resources) được chia cho nhiều dự án"},{"level":1,"text":"Các bước tính toán công suất nguồn lực dùng chung"},{"level":2,"text":"Xác định tổng số giờ và số giờ chi phí chung (overhead hours)"},{"level":2,"text":"Trừ thời gian chi phí chung khỏi tổng thời gian để tính thời gian khả dụng"},{"level":2,"text":"Tổng thời gian – Thời gian chi phí chung = Thời gian khả dụng (Total Time – Overhead Time = Available Time)"},{"level":2,"text":"Chia thời gian khả dụng cho số lượng dự án để xác định họ có thể dành bao nhiêu thời gian cho mỗi dự án"},{"level":2,"text":"Thời gian khả dụng / Số lượng dự án (Available Time / Number of Projects)"},{"level":2,"text":"Phân bổ thời gian"},{"level":1,"text":"Việc biết cách tính toán công suất sẽ hữu ích trong việc chuẩn bị cho mọi tình huống"},{"level":2,"text":"Việc ước tính quá cao tính khả dụng có thể gây chậm trễ dự án"}]},{"id":"g75","part":8,"title":"Vòng đời nguồn lực (The Resource Lifecycle)","blocks":[{"level":1,"text":"4 giai đoạn của vòng đời nguồn lực"},{"level":2,"text":"Mua sắm (Acquisition)"},{"level":2,"text":"Công ty mua sắm hàng hóa và tuyển dụng nhân sự dựa trên quy trình đánh giá nhu cầu do nhà quản lý dự án khởi xướng"},{"level":2,"text":"Sau khi được huy động, nguồn lực cần được bảo trì thường xuyên"},{"level":2,"text":"Sửa chữa (Repairs)"},{"level":2,"text":"Nâng cấp (Upgrades)"},{"level":2,"text":"Theo dõi tồn kho (Inventory Tracking)"},{"level":2,"text":"Bản vá bảo mật (Security Patches)"},{"level":2,"text":"Cập nhật hệ thống (System Updates)"},{"level":2,"text":"Lịch làm việc (Work Schedules)"},{"level":2,"text":"Động lực (Motivation)"},{"level":2,"text":"Hỗ trợ (Support)"},{"level":2,"text":"Phản hồi hiệu suất (Performance Feedback)"},{"level":2,"text":"Bảo trì (Maintenance)"},{"level":2,"text":"Nguồn lực nhận được hỗ trợ vận hành để hoạt động hiệu quả"},{"level":2,"text":"Cải thiện (Improvement)"},{"level":2,"text":"Bao gồm việc nâng cao thiết bị, phần mềm và hiệu suất nhân viên"},{"level":2,"text":"Loại bỏ (Retirement)"},{"level":2,"text":"Cần thông báo trước để chuẩn bị phương án thay thế"},{"level":2,"text":"Ba điều nên nghĩ đến khi chúng ta bàn về việc loại bỏ nguồn lực"},{"level":2,"text":"Phần mềm kết thúc vòng đời (End of Life - EOL Software)"},{"level":2,"text":"Phần mềm đến cuối vòng đời (EOL) là vấn đề phổ biến đối với các công ty"},{"level":2,"text":"EOL nghĩa là nhà cung cấp sẽ không còn cung cấp cập nhật hoặc hỗ trợ cho phần mềm sau một ngày nhất định"},{"level":2,"text":"Các bản vá bảo mật không còn khả dụng đối với phần mềm EOL"},{"level":2,"text":"Thông báo EOL là dấu hiệu để bắt đầu ngừng sử dụng sản phẩm và tìm sản phẩm thay thế"},{"level":2,"text":"Ngừng sử dụng phần cứng (Hardware Decommissioning)"},{"level":2,"text":"Các công ty thường dự trữ thiết bị CNTT dư thừa như laptop và tai nghe trong kho, và nhiều máy chủ ở các địa điểm khác nhau để bảo vệ chuyển đổi dự phòng (failover protection)"},{"level":2,"text":"Sử dụng lưu trữ đám mây để thuê ngoài hiệu quả việc phân phối máy chủ"},{"level":2,"text":"Trong quá trình ngừng sử dụng, nhân viên CNTT khởi động một vòng đời mới để huy động hạ tầng CNTT"},{"level":2,"text":"Lập kế hoạch kế nhiệm (Succession Planning)"},{"level":2,"text":"Một cách tiếp cận chủ động, trong đó các công ty xây dựng kế hoạch xác định người thay thế tiềm năng cho các vai trò trọng yếu khi bị bỏ trống"},{"level":2,"text":"Đó là khi nhân viên rời khỏi vị trí của họ"},{"level":2,"text":"Nhân viên có thể rời khỏi vị trí của họ, hoặc bằng cách chuyển sang một công ty khác, hoặc chuyển sang một vai trò khác trong cùng tổ chức"},{"level":2,"text":"Lập kế hoạch kế nhiệm xác định kiến thức, kỹ năng và trách nhiệm cần thiết cho vị trí, và ghi lại các quy trình liên quan"},{"level":2,"text":"Nó giúp bảo tồn kiến thức của công ty và tăng khả năng phục hồi bằng cách loại bỏ điểm lỗi duy nhất (single point of failure)"}]},{"id":"g76","part":8,"title":"Tiến hành đánh giá nhu cầu (Conduct a Needs Assessment)","blocks":[{"level":1,"text":"Các PM cần huy động đủ nguồn lực để hoàn thành dự án"},{"level":1,"text":"Đôi khi việc sử dụng dưới công suất (Underutilization) cũng có thể là vấn đề lớn không kém việc sử dụng quá công suất (overutilization)"},{"level":1,"text":"Đánh giá nhu cầu (Needs Assessment)"},{"level":2,"text":"Xác định các nguồn lực mà một dự án cần để giải quyết một vấn đề kinh doanh"},{"level":2,"text":"Các nguồn lực này có thể bao gồm kỹ năng, phần mềm, thiết bị và các tài sản hữu hình, vô hình khác"},{"level":2,"text":"Đánh giá nhu cầu phải có chủ đích và có cấu trúc"},{"level":1,"text":"Việc tiến hành đánh giá nhu cầu kỹ lưỡng có thể mang lại nhiều lợi ích, bao gồm việc phát hiện sớm các khoảng trống, cho phép nhóm xem xét nhiều lựa chọn"},{"level":2,"text":"Nó có thể cải thiện hiệu suất đúng tiến độ"},{"level":1,"text":"4 bước tiến hành đánh giá nhu cầu"},{"level":2,"text":"Hiểu các yêu cầu của dự án"},{"level":2,"text":"Mục tiêu dự án (Project Objective)"},{"level":2,"text":"Tiêu chí thành công (Success Criteria)"},{"level":2,"text":"Cột mốc (Milestones)"},{"level":2,"text":"Sản phẩm bàn giao (Deliverables)"},{"level":2,"text":"Xác định các nguồn lực hiện có"},{"level":2,"text":"Hãy nhìn tổng thể vào kho nguồn lực của bạn, bao gồm các thành viên nhóm cụ thể, phần mềm và thiết bị"},{"level":2,"text":"Xác định mọi khoảng trống nguồn lực"},{"level":2,"text":"So sánh tóm tắt trạng thái tương lai và trạng thái hiện tại để xác định mọi khoảng trống nguồn lực"},{"level":2,"text":"Xử lý các khoảng trống"},{"level":2,"text":"Tạo kế hoạch xử lý từng khoảng trống đã xác định và đưa vào thực hiện"},{"level":1,"text":"Đánh giá này sẽ giúp chúng ta xác định các lĩnh vực cần cải thiện và cung cấp lộ trình rõ ràng hướng tới hành trình áp dụng đám mây (cloud adoption journey) của họ"}]},{"id":"g77","part":8,"title":"Phân tích khoảng trống (Gap Analysis)","blocks":[{"level":1,"text":"Phân tích khoảng trống (Gap analysis) so sánh trạng thái hiện tại và trạng thái tương lai để xác định và mô tả các khác biệt"},{"level":1,"text":"Phân tích khoảng trống kỹ năng (Skill Gap Analysis)"},{"level":2,"text":"Xác định các kỹ năng cần thiết mà nhóm hiện chưa có"},{"level":1,"text":"Yêu cầu kỹ năng thường được đo bằng hai tiêu chí"},{"level":2,"text":"Loại (Type)"},{"level":2,"text":"Chỉ các kỹ năng cụ thể cần thiết để hoàn thành công việc, như thiết kế đồ họa, quản lý dự án hoặc một ngôn ngữ lập trình cụ thể"},{"level":2,"text":"Chuyên môn (Expertise)"},{"level":2,"text":"Chỉ mức độ năng lực cần thiết, như mới học (novice), thành thạo (competent) và chuyên gia (expert)"},{"level":1,"text":"Tính năng và chức năng (Feature and Function)"},{"level":2,"text":"Các khả năng và công việc mà nguồn lực vật chất sẽ có thể thực hiện"},{"level":2,"text":"Chức năng (Functions)"},{"level":2,"text":"Các công việc hoặc thao tác cụ thể"},{"level":2,"text":"Tính năng (Features)"},{"level":2,"text":"Các công cụ để kích hoạt các chức năng"},{"level":2,"text":"Để giải quyết mọi khoảng trống về tính năng và chức năng, có thể cần điều chỉnh cấu hình, yêu cầu và kế hoạch"},{"level":1,"text":"Tỷ lệ sử dụng nguồn lực (Resource Utilization)"},{"level":2,"text":"Đo lường hiệu quả của nguồn lực dự án"},{"level":2,"text":"Một nguồn lực được coi là sử dụng dưới công suất (underutilized) nếu tỷ lệ sử dụng dưới 100%, trong khi phân bổ quá mức (overallocation) xảy ra khi tỷ lệ vượt quá 100%"},{"level":1,"text":"Thời gian được phân bổ (Time Allocated)"},{"level":2,"text":"Tổng thời gian mà một nguồn lực được lên lịch làm việc trên bất kỳ công việc nào trong dự án"},{"level":1,"text":"Tổng thời gian khả dụng (Total Time Available)"},{"level":2,"text":"Tổng thời gian mà một nguồn lực có thể làm việc cho dự án"},{"level":1,"text":"Khoảng trống sử dụng (utilization gap) xảy ra khi tỷ lệ sử dụng nguồn lực thực tế khác với tỷ lệ sử dụng mong muốn hoặc mục tiêu"},{"level":2,"text":"Một nguyên nhân có thể của khoảng trống sử dụng dưới công suất là thiếu thứ tự ưu tiên công việc rõ ràng, dẫn đến phân bổ công việc kém hiệu quả"},{"level":2,"text":"Một nguyên nhân khác có thể là nhóm thiếu các kỹ năng cần thiết để hoàn thành công việc, dẫn đến chậm trễ và sử dụng dưới công suất"},{"level":2,"text":"Các khoảng trống sử dụng có thể ảnh hưởng đáng kể đến kết quả dự án"}]},{"id":"g78","part":8,"title":"Tối ưu hóa nguồn lực (Resource Optimization)","blocks":[{"level":1,"text":"Các kỹ thuật tối ưu hóa nguồn lực có thể được áp dụng trong các giai đoạn Planning và Execution của dự án"},{"level":1,"text":"2 kỹ thuật chính của tối ưu hóa nguồn lực"},{"level":2,"text":"Làm mượt nguồn lực (Resource Smoothing)"},{"level":2,"text":"Giảm thiểu sự biến động của việc sử dụng nguồn lực qua các giai đoạn thời gian khác nhau"},{"level":2,"text":"Làm mượt nguồn lực hiệu quả trong việc tinh gọn các dự án đúng tiến độ nhưng có lịch trình không đều"},{"level":2,"text":"Làm mượt tạo ra khối lượng công việc đều đặn từ tuần này sang tuần khác, nhưng nó không cho phép ngày kết thúc bị dịch chuyển"},{"level":2,"text":"Cân bằng nguồn lực (Resource Leveling)"},{"level":2,"text":"Chiến lược tối ưu hóa giảm thiểu biến động và cho phép kéo dài thời gian dự án"},{"level":2,"text":"Cân bằng sẽ sắp xếp lại công việc cho đến khi không còn ai bị sử dụng quá mức, nhưng nó có thể kéo dài ngày kết thúc của dự án"}]},{"id":"g79","part":8,"title":"Các biểu đồ thường dùng (Common Diagrams)","blocks":[{"level":1,"text":"Phân tích khoảng trống nhằm điều tra nguyên nhân của các khoảng trống và các giải pháp tiềm năng"},{"level":1,"text":"Biểu đồ xương cá (Fishbone Diagram)"},{"level":2,"text":"Còn được gọi là biểu đồ Ishikawa hay biểu đồ nguyên nhân - kết quả (Cause and Effect Diagram), giúp hình dung các yếu tố khác nhau tác động như thế nào đến một kết quả duy nhất"},{"level":2,"text":"Bất kỳ nhóm phân loại nào phù hợp với dự án đều có thể được dùng, như cấu trúc phân rã công việc (WBS) trong quản lý dự án hoặc bộ phân loại chuẩn được gọi là 6Ps"},{"level":2,"text":"6 Ps"},{"level":2,"text":"Chính sách (Policy)"},{"level":2,"text":"Quy trình (Process)"},{"level":2,"text":"Con người (People)"},{"level":2,"text":"Chương trình nhà máy (Plant Program)"},{"level":2,"text":"Sản phẩm (Product)"},{"level":1,"text":"Ma trận kỹ năng (Skills matrix) hữu ích để xác định các lĩnh vực cần phát triển"},{"level":2,"text":"Xác định mọi kỹ năng cần thiết cho một dự án và ghi chúng vào ma trận"},{"level":2,"text":"Mỗi thành viên nhóm tự đánh giá mức độ năng lực của mình cho từng kỹ năng"},{"level":1,"text":"Biểu đồ tần suất (Histogram)"},{"level":2,"text":"Một loại biểu đồ cột thường được dùng trong phân tích thống kê"},{"level":2,"text":"Các PM có thể dùng biểu đồ tần suất để tóm tắt các tập dữ liệu lớn, đánh giá quy trình và theo dõi việc sử dụng nguồn lực theo thời gian"}]},{"id":"g80","part":8,"title":"Quy trình quản lý nguồn lực","blocks":[{"level":1,"text":"Các bước quản lý nguồn lực (resource management) không nhất thiết phải tuần tự"},{"level":1,"text":"Quy trình quản lý nguồn lực (Resource Management Process)"},{"level":2,"text":"Ước lượng các nguồn lực cần thiết"},{"level":2,"text":"Bước này yêu cầu thực hiện đánh giá nhu cầu (needs assessment) để xác định nguồn lực con người và vật chất cần thiết nhằm hoàn thành các sản phẩm bàn giao (deliverables) của dự án"},{"level":2,"text":"Đảm bảo các nguồn lực"},{"level":2,"text":"Bước này bao gồm thực hiện phân tích khoảng cách (gap analysis) để xác định nguồn lực nào chưa có và lập kế hoạch để thu thập các nguồn lực cần thiết"},{"level":2,"text":"Việc này có thể bao gồm mua sắm nguồn lực vật chất, bổ sung vật tư tiêu hao, mua thiết bị hoặc thuê dịch vụ bên ngoài"},{"level":2,"text":"Đào tạo các thành viên trong đội"},{"level":2,"text":"Đầu tư vào việc đào tạo đội nhóm để có thể hoàn thành dự án thành công là điều thiết yếu"},{"level":2,"text":"Phân bổ nguồn lực"},{"level":2,"text":"Bước này bao gồm việc gán nguồn lực cho các công việc riêng lẻ và tính đến các vai trò khác nhau cần thiết cho mỗi hoạt động"},{"level":2,"text":"Phân bổ nguồn lực (resource allocation) bao gồm các hoạt động lập lịch dự án và quản lý khối lượng công việc"},{"level":2,"text":"Quản lý khối lượng công việc (Workload Management)"},{"level":2,"text":"Đảm bảo tất cả các nguồn lực đều làm việc ở mức sử dụng hợp lý"},{"level":1,"text":"Quy trình quản lý nguồn lực nên được xem xét lại khi dự án tiến triển để đảm bảo đội luôn có quyền truy cập vào các nguồn lực cần thiết"},{"level":1,"text":"Quản lý nguồn lực thành công là yếu tố then chốt quyết định thành công của dự án"},{"level":2,"text":"Ước lượng các nguồn lực cần thiết"},{"level":2,"text":"Đảm bảo các nguồn lực"},{"level":2,"text":"Đào tạo các thành viên trong đội"},{"level":2,"text":"Phân bổ nguồn lực cho các công việc cụ thể"},{"level":2,"text":"Giám sát các nguồn lực của dự án; Quản lý rủi ro"}]},{"id":"g81","part":9,"title":"Quản lý rủi ro","blocks":[{"level":1,"text":"Mọi dự án đều phải đối mặt với rủi ro, và không có kế hoạch nào có thể đảm bảo hoàn toàn tiến trình suôn sẻ"},{"level":1,"text":"Rủi ro (Risks)"},{"level":2,"text":"Những sự kiện không lường trước có thể ảnh hưởng tích cực hoặc tiêu cực đến dự án"},{"level":1,"text":"Quản lý rủi ro (risk management), quản lý vấn đề (issue management) và quản lý thay đổi (change management) là các quy trình liên kết với nhau trong quản lý dự án"},{"level":2,"text":"Quy trình quản lý rủi ro bao gồm xác định các rủi ro và thiết lập kế hoạch ứng phó cho các rủi ro đó"},{"level":2,"text":"Vấn đề (issues) là các sự kiện đang diễn ra, đòi hỏi sự chú ý và xử lý khắc phục ngay lập tức"},{"level":2,"text":"Thay đổi (changes) là những điều chỉnh về phạm vi, ngân sách hoặc tiến độ dự án, đòi hỏi phải điều chỉnh các hoạt động hoặc nguồn lực của dự án"},{"level":1,"text":"Rủi ro có thể có tác động vừa tiêu cực vừa tích cực đến dự án"},{"level":1,"text":"Khi một rủi ro đã được ghi nhận xảy ra, nó trở thành một vấn đề"},{"level":1,"text":"Các thay đổi trong dự án cũng có thể bị kích hoạt bởi các vấn đề"},{"level":1,"text":"Quy trình quản lý rủi ro bao gồm bốn nhiệm vụ chính"},{"level":2,"text":"Xác định rủi ro (Risk Identification)"},{"level":2,"text":"Bao gồm việc lập danh sách toàn diện các rủi ro tiềm ẩn, tinh chỉnh danh sách đó và duy trì nó trong sổ đăng ký rủi ro (risk register)"},{"level":2,"text":"Phân tích rủi ro (Risk Analysis)"},{"level":2,"text":"Đánh giá khả năng xảy ra và tác động của từng rủi ro đã xác định để xếp thứ tự ưu tiên"},{"level":2,"text":"Xử lý rủi ro (Risk Treatment)"},{"level":2,"text":"Bao gồm việc xây dựng kế hoạch ứng phó cho từng rủi ro đã xác định"},{"level":2,"text":"Giám sát rủi ro (Risk Monitoring)"},{"level":2,"text":"Bao gồm theo dõi tiến độ của các kế hoạch ứng phó và cập nhật sổ đăng ký rủi ro"},{"level":1,"text":"Phân tích rủi ro định tính (Qualitative Risk Analysis)"},{"level":2,"text":"Phương pháp chủ quan dựa vào nhận thức và diễn giải cá nhân về các rủi ro, sử dụng các thang đo cơ bản để đánh giá chúng"},{"level":2,"text":"Hai yếu tố chính cần xem xét trong phân tích định tính là tính liên kết (interconnectivity) và khả năng phát hiện (detectability)"},{"level":1,"text":"Phân tích rủi ro định lượng (Quantitative Risk Analysis)"},{"level":2,"text":"Kỹ thuật khách quan sử dụng dữ liệu có thể kiểm chứng để chấm điểm các rủi ro của dự án"},{"level":2,"text":"Các phương pháp định lượng này đưa ra ước lượng xác suất chính xác hơn và giúp ưu tiên, quản lý các rủi ro có tác động lớn"},{"level":1,"text":"4 chiến lược xử lý rủi ro tiêu cực"},{"level":2,"text":"Tránh né (Avoidance)"},{"level":2,"text":"Giảm thiểu (Mitigation)"},{"level":2,"text":"Chuyển giao (Transfer)"},{"level":2,"text":"Chấp nhận (Acceptance)"},{"level":1,"text":"4 chiến lược xử lý rủi ro tích cực"},{"level":2,"text":"Khai thác (Exploitation)"},{"level":2,"text":"Tăng cường (Enhancement)"},{"level":2,"text":"Chia sẻ (Sharing)"},{"level":2,"text":"Chấp nhận (Acceptance)"},{"level":1,"text":"Kế hoạch giảm thiểu rủi ro (Risk Mitigation Plan)"},{"level":2,"text":"Được xây dựng để giảm thiểu tác động của các rủi ro tiêu cực và tối đa hóa lợi ích của các rủi ro tích cực"},{"level":1,"text":"Kế hoạch dự phòng (Contingency Plan)"},{"level":2,"text":"Còn được gọi là kế hoạch dự phòng (fallback) hoặc kế hoạch dự trữ (backup), được tạo ra để ứng phó trong trường hợp rủi ro xảy ra, giúp phản ứng và phục hồi nhanh chóng"},{"level":1,"text":"Sổ đăng ký rủi ro (risk register) được dùng để ghi nhận các rủi ro của dự án và bao gồm các trường thiết yếu"},{"level":2,"text":"Mã rủi ro (Risk ID)"},{"level":2,"text":"Mô tả (Description)"},{"level":2,"text":"Tóm tắt phân tích (Analysis Summary)"},{"level":2,"text":"Tiêu chí chấm điểm ưu tiên (Priority Scoring Criteria)"},{"level":2,"text":"Người chịu trách nhiệm (Owner)"},{"level":2,"text":"Ứng phó (Response)"},{"level":1,"text":"Kế hoạch chuyển giao (Transition Plan)"},{"level":2,"text":"Phác thảo cách đội dự án chuyển giao quyền sở hữu sản phẩm cho các chủ sở hữu lâu dài"},{"level":1,"text":"Kế hoạch chuyển giao nội bộ và bên ngoài khác nhau về mức độ trang trọng và trọng tâm"},{"level":2,"text":"Các kế hoạch nội bộ có thể ít trang trọng hơn và dùng ngôn ngữ riêng của công ty, trong khi các kế hoạch bên ngoài tuân thủ hợp đồng và loại bỏ thuật ngữ nội bộ"}]},{"id":"g82","part":9,"title":"So sánh rủi ro, vấn đề và thay đổi","blocks":[{"level":1,"text":"Quản lý rủi ro, quản lý vấn đề và quản lý thay đổi là các quy trình liên quan lẫn nhau, đòi hỏi các cách tiếp cận khác nhau để tạo ra kế hoạch quản lý riêng biệt"},{"level":1,"text":"Rủi ro (Risks)"},{"level":2,"text":"Các sự kiện tiềm ẩn trong tương lai, có thể xảy ra hoặc không"},{"level":1,"text":"Vấn đề (Issues)"},{"level":2,"text":"Các sự kiện đang diễn ra, đòi hỏi sự chú ý và xử lý khắc phục ngay lập tức"},{"level":1,"text":"Thay đổi (Changes)"},{"level":2,"text":"Những điều chỉnh về phạm vi, ngân sách hoặc tiến độ dự án, đòi hỏi phải điều chỉnh các hoạt động hoặc nguồn lực của dự án"},{"level":1,"text":"Kiểm soát thay đổi (change control) đánh giá các yêu cầu thay đổi mới và theo dõi các thay đổi đã hoàn thành"},{"level":1,"text":"Mặc dù rủi ro thường mang hàm ý tiêu cực, chúng cũng có thể có tác động tích cực đến dự án"},{"level":1,"text":"Một đánh giá rủi ro toàn diện có thể giúp dự án chuẩn bị cho các vấn đề tiềm ẩn"},{"level":1,"text":"Việc lập kế hoạch ứng phó rủi ro có thể đòi hỏi thay đổi kế hoạch dự án, đặc biệt khi khả năng xảy ra và tác động của rủi ro ở mức cao"},{"level":1,"text":"Các thay đổi trong dự án cũng có thể bị kích hoạt bởi các vấn đề"},{"level":2,"text":"Khi một vấn đề phát sinh, nó phải được đánh giá về mức độ ưu tiên và cách ứng phó, có thể dẫn đến khắc phục ngay lập tức, không hành động gì, hoặc thay đổi kế hoạch dự án"}]},{"id":"g83","part":9,"title":"Tổng quan về quản lý rủi ro","blocks":[{"level":1,"text":"Quản lý rủi ro (risk management) bao gồm việc dự đoán trước các rủi ro tiềm ẩn và xây dựng các chiến lược chủ động để xử lý chúng"},{"level":1,"text":"4 nhiệm vụ chính của quy trình quản lý rủi ro"},{"level":2,"text":"Xác định rủi ro"},{"level":2,"text":"Lập danh sách toàn diện tất cả các rủi ro tiềm ẩn, dựa trên kinh nghiệm trong quá khứ, môi trường hiện tại và các dự án khác"},{"level":2,"text":"Phân tích rủi ro"},{"level":2,"text":"Đánh giá khả năng xảy ra của từng rủi ro đã xác định và tác động tiềm ẩn của nó"},{"level":2,"text":"Xử lý rủi ro"},{"level":2,"text":"Xây dựng chiến lược quản lý rủi ro cho từng rủi ro đã xác định, chỉ định người chịu trách nhiệm (owner) và kế hoạch ứng phó cho từng rủi ro"},{"level":2,"text":"Giám sát rủi ro"},{"level":2,"text":"Thiết lập kế hoạch giám sát các rủi ro trong suốt dự án, bao gồm theo dõi tiến độ của các kế hoạch ứng phó và theo dõi sự xuất hiện của các sự kiện rủi ro"},{"level":1,"text":"Bằng cách tuân theo quy trình quản lý rủi ro này, hãy chuẩn bị cho các rủi ro tiềm ẩn và giảm thiểu tác động của chúng"},{"level":1,"text":"Rủi ro có thể được phân loại thành rủi ro đã biết (known) hoặc chưa biết (unknown)"},{"level":1,"text":"Mục đích của đánh giá quản lý rủi ro là giảm số lượng các rủi ro chưa biết"},{"level":1,"text":"Bằng cách thu thập và tổng hợp ý kiến đóng góp từ tất cả các bên liên quan, danh sách rủi ro có thể được mở rộng đáng kể và lượng rủi ro chưa biết có thể được giảm đáng kể"},{"level":1,"text":"Quy trình quản lý rủi ro làm giảm số lượng các rủi ro chưa biết, tạo nên một dự án có khả năng phục hồi tốt"},{"level":1,"text":"Không thể loại bỏ hoàn toàn mọi rủi ro"},{"level":1,"text":"Một số vai trò về rủi ro cần xem xét"},{"level":2,"text":"Chủ sở hữu rủi ro (Risk Owner)"},{"level":2,"text":"Người chịu trách nhiệm quản lý một rủi ro, xây dựng kế hoạch giảm thiểu và ứng phó rủi ro, và là người đầu tiên được thông báo khi rủi ro xảy ra"},{"level":2,"text":"Nhà quản lý rủi ro (Risk Manager)"},{"level":2,"text":"Quản trị sổ đăng ký rủi ro và dẫn dắt toàn bộ quy trình quản lý rủi ro, bao gồm phân tích và ứng phó rủi ro"},{"level":2,"text":"Ban quản lý cấp cao (Senior Management)"},{"level":2,"text":"Chịu trách nhiệm quản lý các rủi ro của tổ chức và có thể trở thành các bên liên quan đối với các rủi ro cụ thể trong dự án tùy thuộc vào mức độ ưu tiên và bản chất của chúng"}]},{"id":"g84","part":9,"title":"Rủi ro nội bộ và rủi ro bên ngoài","blocks":[{"level":1,"text":"Trong giai đoạn lập kế hoạch (planning phase) của dự án, người quản lý dự án (PM) tổ chức một cuộc họp đánh giá rủi ro"},{"level":2,"text":"Buổi họp này có sự tham gia của đội dự án, các bên liên quan chính, các chuyên gia chuyên môn (SMEs) và nhà tài trợ dự án (project sponsor)"},{"level":2,"text":"Đội sẽ cùng động não (brainstorm) tất cả những điều có thể xảy ra với dự án — cả tốt và xấu"},{"level":2,"text":"Đội sẽ đánh giá từng rủi ro để xác định khả năng xảy ra và tác động của nó đến dự án"},{"level":2,"text":"Đội sẽ lập kế hoạch về những việc cần làm nếu từng rủi ro xảy ra"},{"level":2,"text":"Đội ghi lại tất cả các rủi ro và cách ứng phó của chúng trong sổ đăng ký rủi ro (risk register)"},{"level":1,"text":"Sự khác biệt giữa rủi ro nội bộ và rủi ro bên ngoài"},{"level":2,"text":"Rủi ro nội bộ (Internal Risk)"},{"level":2,"text":"Xuất phát từ bên trong tổ chức"},{"level":2,"text":"Các rủi ro nội bộ phổ biến bao gồm"},{"level":2,"text":"Các dự án"},{"level":2,"text":"Một trong các rủi ro là khả năng mất nguồn lực do công ty phê duyệt một dự án mới có mức độ ưu tiên cao hơn"},{"level":2,"text":"Chuyển đổi số (Digital Transformation)"},{"level":2,"text":"Các công ty đầu tư vào chuyển đổi số thường đánh giá hệ thống công nghệ (technology stack) hiện tại và áp dụng các sản phẩm hiện đại"},{"level":2,"text":"Ban quản lý mới (New Management)"},{"level":2,"text":"Sự thay đổi trong ban quản lý cấp cao cũng có thể ảnh hưởng đến kết quả dự án, vì các ưu tiên của họ chi phối hoạt động của tổ chức và danh mục dự án"},{"level":2,"text":"Tái cơ cấu (Reorganization)"},{"level":2,"text":"Tái cơ cấu là một rủi ro khác đối với các dự án, khi những thay đổi về cơ cấu báo cáo, chức danh, các bên liên quan và nhà tài trợ dự án có thể ảnh hưởng đến sự vận hành của đội và tiến độ dự án"},{"level":2,"text":"Sáp nhập và mua lại (Merger and Acquisition)"},{"level":2,"text":"Nó có thể tạo ra các rủi ro mới, như sự khác biệt về văn hóa công ty, phong cách làm việc, quy trình và hệ thống công nghệ (technology stacks)"},{"level":2,"text":"Rủi ro bên ngoài (External Risk)"},{"level":2,"text":"Xuất phát từ bên ngoài tổ chức"},{"level":2,"text":"Các rủi ro bên ngoài phổ biến bao gồm"},{"level":2,"text":"Hạ tầng hết vòng đời hỗ trợ (Infrastructure End-Of-Life / EOL)"},{"level":2,"text":"Một công nghệ hoặc sản phẩm không còn được nhà cung cấp hỗ trợ hoặc duy trì"},{"level":2,"text":"Sự cố an ninh mạng (Cybersecurity Incidents)"},{"level":2,"text":"Các sự cố này xảy ra khi các bên trái phép truy cập vào hệ thống máy tính của tổ chức, dẫn đến việc đánh cắp, sửa đổi hoặc chiếm đoạt dữ liệu"},{"level":2,"text":"Thay đổi môi trường pháp lý (Regulatory Environment Changes)"},{"level":2,"text":"Các vi phạm tuân thủ (compliance) có thể dẫn đến tác động bất lợi nghiêm trọng, bao gồm tiền phạt, kế hoạch khắc phục, tái kiểm tra, hoặc thậm chí lệnh đóng cửa"}]},{"id":"g85","part":9,"title":"Phân tích rủi ro định tính","blocks":[{"level":1,"text":"Phân tích rủi ro định tính (Qualitative Risk Analysis) là phương pháp chủ quan dựa vào nhận thức và diễn giải cá nhân về các rủi ro"},{"level":1,"text":"Có hai yếu tố chính cần xem xét khi bàn về phân tích rủi ro định tính"},{"level":2,"text":"Tính liên kết (Interconnectivity)"},{"level":2,"text":"Đề cập đến cách một rủi ro có thể gây tác động rộng hơn vượt ra ngoài một sự kiện đơn lẻ"},{"level":2,"text":"Phân tích tính liên kết bao gồm việc đánh giá cách các rủi ro của dự án có thể tương tác với nhau"},{"level":2,"text":"Khả năng phát hiện (Detectability)"},{"level":2,"text":"Một thước đo thiết yếu về mức độ nhanh chóng mà một rủi ro có thể được phát hiện nếu nó xảy ra"},{"level":2,"text":"Khả năng phát hiện có thể ảnh hưởng đến phạm vi và tác động của một sự kiện rủi ro"},{"level":2,"text":"Các rủi ro có khả năng phát hiện thấp có thể bị bỏ sót và chỉ được phát hiện sau khi đã đến tay người dùng cuối"},{"level":1,"text":"Phân tích định tính có thể được gán các giá trị định lượng"}]},{"id":"g86","part":9,"title":"Phân tích rủi ro định lượng","blocks":[{"level":1,"text":"Phân tích rủi ro định lượng (Quantitative Risk Analysis) là kỹ thuật khách quan sử dụng dữ liệu có thể kiểm chứng để chấm điểm các rủi ro của dự án"},{"level":1,"text":"Phân phối xác suất (Probability Distribution)"},{"level":2,"text":"Một cách mô tả khả năng xảy ra của mỗi kết quả có thể"},{"level":2,"text":"Một giá trị trung bình đơn lẻ chỉ chạm đến bề mặt của sự phức tạp thực sự của một phân phối"},{"level":1,"text":"Các mô phỏng (simulations) đưa ra ước lượng xác suất đáng tin cậy cho các rủi ro có tác động lớn"},{"level":1,"text":"Cần nhớ rằng độ chính xác của mô phỏng phụ thuộc vào chất lượng dữ liệu đầu vào"},{"level":1,"text":"Hai thước đo phổ biến nhất của rủi ro là xác suất (probability) và tác động (impact)"},{"level":1,"text":"Xác suất (Probability)"},{"level":2,"text":"Đo lường khả năng xảy ra của một rủi ro và có thể được biểu diễn trên thang số hoặc thang tương đối"},{"level":2,"text":"Thang số thường dao động từ 0 đến 1, trong đó 1 thể hiện khả năng xảy ra 100%"},{"level":2,"text":"Hầu hết các thang xác suất loại trừ 0 và 1"},{"level":1,"text":"Tác động (Impact)"},{"level":2,"text":"Đo lường mức độ một rủi ro sẽ ảnh hưởng đến doanh nghiệp nếu nó xảy ra, và có thể được biểu diễn trên thang số hoặc thang tương đối"},{"level":2,"text":"Một đánh giá tác động đa chiều có thể được dùng để đo lường cách rủi ro ảnh hưởng đến các chỉ số kinh doanh khác nhau, như chi phí, thời gian hoặc phạm vi"},{"level":1,"text":"Xác suất và tác động thường được đo lường cùng nhau để tạo thành một ma trận hoặc thang đo theo góc phần tư (quadrant scale)"},{"level":1,"text":"Đánh giá tác động-xác suất (probability impact assessment) là điểm khởi đầu tốt cho việc phân tích rủi ro"},{"level":1,"text":"Phân tích chế độ lỗi và ảnh hưởng (Failure Mode and Effect Analysis / FMEA)"},{"level":2,"text":"Một phân tích chi tiết về một quy trình đơn lẻ để xác định nhiều rủi ro"},{"level":2,"text":"FMEA có thể chủ động xác định và loại bỏ các khiếm khuyết trong thiết kế trong quá trình thiết kế sản phẩm và quy trình"},{"level":2,"text":"Đây là một tài liệu sống, đòi hỏi khá nhiều thời gian và phân tích để duy trì khi quy trình thay đổi"},{"level":1,"text":"Phân tích kịch bản (Scenario Analysis)"},{"level":2,"text":"Còn được gọi là phân tích tình huống (situational analysis) hoặc phân tích giả định (what-if analysis), là một quy trình bao gồm việc tạo ra các sự kiện tiềm ẩn và đánh giá tác động của chúng"},{"level":2,"text":"Đặc biệt hữu ích để đánh giá các sự kiện có xác suất thấp nhưng tác động lớn, như thiên tai hoặc các cuộc tấn công ransomware"},{"level":2,"text":"Quy trình phân tích kịch bản bao gồm việc đặt các câu hỏi giả định \"what-if\""},{"level":2,"text":"Ví dụ"},{"level":2,"text":"Điều gì xảy ra với Y nếu tôi thay đổi X?"},{"level":2,"text":"Nếu X xảy ra, nó sẽ ảnh hưởng đến Y như thế nào?"},{"level":2,"text":"Một sự thay đổi ở X ảnh hưởng đến Y ra sao?"},{"level":2,"text":"Phân tích kịch bản là một công cụ hữu ích có thể giúp cá nhân và tổ chức chuẩn bị cho các sự kiện bất ngờ và đưa ra quyết định sáng suốt về quản lý rủi ro"}]},{"id":"g87","part":9,"title":"Các chiến lược quản lý rủi ro","blocks":[{"level":1,"text":"Quản lý rủi ro xác định các rủi ro và tối ưu hóa tác động"},{"level":1,"text":"Chiến lược quản lý rủi ro phác thảo cách xử lý từng rủi ro trong trường hợp nó xảy ra, còn được gọi là \"ứng phó rủi ro (risk response)\" hoặc \"xử lý rủi ro (risk treatment)\""},{"level":1,"text":"4 chiến lược xử lý rủi ro tiêu cực"},{"level":2,"text":"Tránh né rủi ro (Risk Avoidance)"},{"level":2,"text":"Ngăn rủi ro xảy ra bằng cách tránh bất cứ điều gì có thể gây ra sự kiện đó"},{"level":2,"text":"Giảm thiểu rủi ro (Risk Mitigation)"},{"level":2,"text":"Nhằm giảm tác động hoặc khả năng xảy ra của một rủi ro"},{"level":2,"text":"Chuyển giao rủi ro (Risk Transfer)"},{"level":2,"text":"Chuyển rủi ro cho một bên thứ ba, chuyển trách nhiệm tài chính của rủi ro sang người khác"},{"level":2,"text":"Chấp nhận rủi ro (Risk Acceptance)"},{"level":2,"text":"Phương pháp \"không làm gì cả\" chấp nhận hậu quả của một rủi ro nếu nó xảy ra"},{"level":1,"text":"4 chiến lược xử lý rủi ro tích cực"},{"level":2,"text":"Khai thác rủi ro (Risk Exploitation)"},{"level":2,"text":"Thực hiện các bước để đảm bảo sự kiện đó xảy ra"},{"level":2,"text":"Tăng cường rủi ro (Risk Enhancement)"},{"level":2,"text":"Tối đa hóa tác động tích cực của một rủi ro"},{"level":2,"text":"Chia sẻ rủi ro (Risk Sharing)"},{"level":2,"text":"Tìm những bên khác cũng sẽ được hưởng lợi từ rủi ro và chia sẻ nó với họ"},{"level":2,"text":"Chấp nhận rủi ro (Risk Acceptance)"},{"level":2,"text":"Phương pháp \"không làm gì cả\" mà trong đó bạn tận hưởng lợi ích nếu rủi ro xảy ra và không nhận được lợi ích nào nếu nó không xảy ra"}]},{"id":"g88","part":9,"title":"Kế hoạch giảm thiểu và kế hoạch dự phòng","blocks":[{"level":1,"text":"Sau khi một rủi ro đã được phân tích và phương án xử lý đã được chọn, chủ sở hữu rủi ro (risk owner) xây dựng một kế hoạch giảm thiểu được triển khai trước khi rủi ro xảy ra"},{"level":2,"text":"Kế hoạch giảm thiểu rủi ro (risk mitigation plan) giảm thiểu tác động của các rủi ro tiêu cực và tối đa hóa lợi ích của các rủi ro tích cực"},{"level":2,"text":"Mặc dù có tên là \"giảm thiểu (mitigation)\", kế hoạch này áp dụng được cho mọi chiến lược ứng phó rủi ro"},{"level":1,"text":"Sau khi phương án xử lý rủi ro đã được chọn, chủ sở hữu rủi ro tạo ra một kế hoạch dự phòng (contingency plan), còn được gọi là kế hoạch dự phòng (fallback) hoặc kế hoạch dự trữ (backup)"},{"level":1,"text":"Kế hoạch dự phòng (Contingency Plan)"},{"level":2,"text":"Phác thảo cách ứng phó trong trường hợp rủi ro xảy ra"},{"level":2,"text":"Một kế hoạch dự phòng, tối thiểu, nên bao gồm các thông tin sau"},{"level":2,"text":"Tín hiệu kích hoạt (trigger) báo hiệu rủi ro đã xảy ra"},{"level":2,"text":"Các quy trình ứng phó tức thì"},{"level":2,"text":"Các phản ứng theo thời gian hoặc theo giai đoạn, bao gồm phản ứng tức thì, theo dõi tiếp (follow-up) và các giai đoạn phục hồi"},{"level":2,"text":"Chi tiết liên lạc, như các đầu mối chính, ai cần được thông báo, và thủ tục leo thang (escalation)"},{"level":2,"text":"Kế hoạch dự phòng là cần thiết cho mỗi rủi ro có mức độ ưu tiên cao"},{"level":1,"text":"Quy trình quản lý rủi ro thu thập mọi thông tin rủi ro cần thiết, sau đó được tổng hợp vào sổ đăng ký rủi ro (risk register)"},{"level":2,"text":"Sổ đăng ký rủi ro bao gồm một số trường thiết yếu"},{"level":2,"text":"Mã rủi ro (Risk ID)"},{"level":2,"text":"Mô tả rủi ro (Risk Description)"},{"level":2,"text":"Tóm tắt phân tích rủi ro (Risk Analysis Summary)"},{"level":2,"text":"Tiêu chí chấm điểm tác động hoặc mức độ ưu tiên (Impact or Priority Scoring Criteria)"},{"level":2,"text":"Mức độ ưu tiên hoặc xếp hạng rủi ro (Risk Priority or Ranking)"},{"level":2,"text":"Chủ sở hữu rủi ro (Risk Owner)"},{"level":2,"text":"Ứng phó hoặc xử lý rủi ro (Risk Response or Treatment)"},{"level":2,"text":"Sổ đăng ký rủi ro được tạo và điền dữ liệu lần đầu trong đợt đánh giá rủi ro ban đầu"},{"level":2,"text":"Việc cập nhật sổ đăng ký là rất quan trọng khi xác suất hoặc tác động của một rủi ro thay đổi, để nguồn lực có thể tập trung vào các hạng mục có mức độ ưu tiên cao hơn"},{"level":1,"text":"Báo cáo rủi ro (Risk Report)"},{"level":2,"text":"Chia sẻ thông tin liên quan về quy trình quản lý rủi ro của dự án và được chia sẻ trong suốt thời gian còn lại của dự án"},{"level":2,"text":"Báo cáo rủi ro nên bao gồm bản tóm tắt sau"},{"level":2,"text":"Trạng thái hiện tại của các rủi ro dự án"},{"level":2,"text":"Tổng số rủi ro đã xác định"},{"level":2,"text":"Xu hướng (Trends)"},{"level":2,"text":"Tóm tắt các rủi ro đã xảy ra"},{"level":2,"text":"Các tác động về tài chính, tiến độ và phạm vi do các rủi ro đã xảy ra gây ra"},{"level":2,"text":"Các rủi ro mới nổi đáng chú ý"},{"level":2,"text":"Các rủi ro đáng chú ý có tác động lớn và nhạy cảm về thời gian"},{"level":2,"text":"Trạng thái rủi ro dự báo"},{"level":2,"text":"Báo cáo rủi ro (risk reporting) tóm tắt trạng thái rủi ro của dự án và cách nó ảnh hưởng đến dự án"},{"level":1,"text":"PM bắt đầu bằng việc tạo một kế hoạch quản lý rủi ro phác thảo phương pháp và các công cụ sẽ được dùng trong quy trình quản lý rủi ro"},{"level":2,"text":"Kế hoạch xác định rủi ro nên được đưa vào và nêu chi tiết cách đội sẽ xác định các rủi ro"},{"level":2,"text":"Cấu trúc phân rã rủi ro (Risk Breakdown Structure / RBS) nên được tạo ra để phân loại bản chất các rủi ro theo nhóm"},{"level":2,"text":"Chiến lược ứng phó rủi ro nên tóm tắt các lựa chọn được dùng để quản lý rủi ro"},{"level":2,"text":"Các yếu tố tài chính, như tính khả dụng của nguồn vốn, nhu cầu vốn, hoặc yêu cầu về nguồn lực, nên được liệt kê"},{"level":2,"text":"Kế hoạch giám sát rủi ro nên mô tả cách PM và các chủ sở hữu rủi ro sẽ xác định và theo dõi các rủi ro"},{"level":2,"text":"Phác thảo thời gian của mọi hoạt động quản lý rủi ro"},{"level":2,"text":"Cuộc họp đánh giá rủi ro ban đầu"},{"level":2,"text":"Báo cáo rủi ro định kỳ (ongoing risk reporting)"},{"level":2,"text":"Các hoạt động định kỳ khác"}]},{"id":"g89","part":9,"title":"Kế hoạch chuyển giao","blocks":[{"level":1,"text":"Kế hoạch chuyển giao (Transition Plan)"},{"level":2,"text":"Phác thảo cách đội dự án sẽ chuyển giao quyền sở hữu sản phẩm cho các chủ sở hữu lâu dài khi kết thúc dự án"},{"level":2,"text":"Nó cũng cho phép đội đưa các hoạt động chuyển giao vào tiến độ của dự án"},{"level":1,"text":"Sau khi dự án hoàn thành, sản phẩm bước vào giai đoạn bảo trì"},{"level":1,"text":"Đội vận hành (operations team) sau đó tiếp quản giai đoạn bảo trì, bao gồm hỗ trợ thường xuyên, cập nhật và cải tiến quy trình"},{"level":1,"text":"Kế hoạch chuyển giao có thể ở dạng một danh sách kiểm tra (checklist) hoặc một tài liệu chi tiết"},{"level":2,"text":"Các yếu tố chính cần đưa vào kế hoạch"},{"level":2,"text":"Vai trò và trách nhiệm (Roles and Responsibilities)"},{"level":2,"text":"Xác định ai chịu trách nhiệm hoàn thành các hoạt động chuyển giao, ai sẽ sở hữu các hoạt động bảo trì, và ai sẽ phụ trách kế hoạch chuyển giao"},{"level":2,"text":"Lịch trình chuyển giao (Transition Schedule)"},{"level":2,"text":"Xác định lịch trình của các hoạt động chuyển giao, bao gồm ngày kết thúc chính thức của dự án và ngày vận hành (go-live date)"},{"level":2,"text":"Lịch trình bảo trì (Maintenance Schedule)"},{"level":2,"text":"Xác định các yêu cầu bảo trì liên tục và lịch trình các hoạt động mà đội vận hành cần đưa vào công việc của họ"},{"level":2,"text":"Đào tạo (Training)"},{"level":2,"text":"Xác định các yêu cầu đào tạo vận hành và các kênh đào tạo cần thiết để đào tạo đội bảo trì, bao gồm đào tạo trên máy tính hoặc các buổi đào tạo do chuyên gia dẫn dắt"},{"level":2,"text":"Các hoạt động (Activities)"},{"level":2,"text":"Liệt kê tất cả các công việc khác cần thiết để hoàn thành việc bàn giao, bao gồm thiết lập quyền truy cập, bàn giao tài sản và các buổi rà soát"},{"level":2,"text":"Công cụ và kỹ thuật (Tools and Techniques)"},{"level":2,"text":"Liệt kê bất kỳ công cụ, kỹ thuật hoặc quy trình cụ thể nào mà đội vận hành sẽ cần dùng lâu dài"},{"level":2,"text":"Tài liệu sản phẩm (Product Documentation)"},{"level":2,"text":"Tài liệu mã nguồn, đặc tả sản phẩm, cấu hình, và quyền truy cập cùng thông tin đăng nhập"},{"level":2,"text":"Kế hoạch bàn giao tài sản (Asset Turnover Plan)"},{"level":2,"text":"Xây dựng chiến lược về cách thức và thời điểm tài sản sẽ được chuyển từ đội dự án sang đội bảo trì"},{"level":2,"text":"Phân tích tác động (Impact Analysis)"},{"level":2,"text":"Xác định cách việc triển khai thành công dự án sẽ thay đổi công việc"},{"level":1,"text":"Trong giai đoạn vận hành (go-live phase), đội dự án dẫn dắt các nỗ lực trong khi vẫn cập nhật thông tin cho đội vận hành"},{"level":1,"text":"Việc xác định rõ ràng thời điểm bàn giao vận hành trong lịch trình dự án là điều thiết yếu"},{"level":1,"text":"Kế hoạch chuyển giao được tạo ra cho cả đối tượng nội bộ và bên ngoài"},{"level":1,"text":"Kế hoạch chuyển giao nội bộ có thể trang trọng hoặc không trang trọng, tùy thuộc vào thủ tục của tổ chức"},{"level":1,"text":"Kế hoạch chuyển giao bên ngoài thường trang trọng hơn các kế hoạch nội bộ"},{"level":1,"text":"Trong một số trường hợp, việc bàn giao dự án có thể bao gồm việc thay đổi nhà cung cấp. Lập lịch trình dự án (Creating a Project Schedule)"}]},{"id":"g90","part":10,"title":"Lập lịch trình dự án","blocks":[{"level":1,"text":"Ước lượng chi phí, xác định nguồn lực và lập kế hoạch trình tự có thể khiến một dự án trông có vẻ choáng ngợp"},{"level":1,"text":"Các dự án Waterfall dùng Cấu trúc phân rã công việc (Work Breakdown Structure / WBS) cho mục đích này, trong khi các dự án Agile dùng backlog dự án"},{"level":2,"text":"Mức độ chi tiết cần thiết khi phân rã một dự án phụ thuộc vào từng dự án và đội cụ thể"},{"level":1,"text":"Các đội Agile hướng tới việc tạo ra một sản phẩm có thể phát hành được trong các khoảng thời gian cố định gọi là sprint"},{"level":1,"text":"Mục tiêu sprint (sprint goal) thể hiện tiến độ dự án và nằm trong tầm kiểm soát của đội phát triển"},{"level":1,"text":"Nhịp độ (cadence) quyết định quy mô của các hạng mục công việc và tần suất điều chỉnh kế hoạch"},{"level":1,"text":"Khi tạo Cấu trúc phân rã công việc (WBS), có một số thành phần chính và hướng dẫn thiết kế cần xem xét"},{"level":2,"text":"Các phần tử (elements) là các sản phẩm bàn giao trong WBS, được biểu diễn bằng các ô hoặc hàng, trong khi các gói công việc (work packages) là các phần tử thấp nhất không có phần tử con và thể hiện công việc hướng theo kết quả"},{"level":2,"text":"Các cấp độ (levels) chỉ lớp của WBS nơi một phần tử nằm, và sơ đồ đánh số (numbering schemes) gán một con số cho mỗi phần tử dựa trên thứ bậc của nó"},{"level":2,"text":"Các nhánh (legs) và cành (branches) lần lượt đề cập đến nhóm các phần tử có tổ tiên chung và nhiều phần tử không thể hiện toàn bộ phần tử cấp cao nhất"},{"level":1,"text":"Backlog đóng vai trò là khối công việc mà đội sẽ hoàn thành, và nó được chủ sở hữu backlog (backlog owner) liên tục tinh chỉnh và điều chỉnh"},{"level":1,"text":"Backlog đặc biệt hữu ích cho các dự án có nhiều yếu tố chưa biết, vì chúng mang lại sự linh hoạt trong ranh giới cố định để tránh phình phạm vi (scope creep)"},{"level":1,"text":"Những khác biệt chính giữa WBS và backlog dự án"},{"level":2,"text":"WBS"},{"level":2,"text":"Kiểm soát phạm vi, thời gian và chi phí"},{"level":2,"text":"Chi tiết được lưu trong từ điển WBS (WBS dictionary)"},{"level":2,"text":"Giả định rằng mọi hạng mục phạm vi sẽ được bàn giao"},{"level":2,"text":"Backlog (Agile)"},{"level":2,"text":"Ưu tiên sự linh hoạt trong khi cố định thời gian và chi phí"},{"level":2,"text":"Chi tiết nằm trong các hạng mục backlog"},{"level":2,"text":"Làm việc trên từng bộ sản phẩm bàn giao một"},{"level":1,"text":"Các công việc của dự án (Project Tasks)"},{"level":2,"text":"Các hành động cụ thể được thực hiện để hoàn thành sản phẩm bàn giao và không phải lúc nào cũng cần ghi chép chi tiết"},{"level":1,"text":"Các mối phụ thuộc (dependencies) đóng vai trò quan trọng trong việc sắp xếp trình tự các hoạt động của dự án"},{"level":2,"text":"4 loại mối phụ thuộc"},{"level":2,"text":"Kết thúc để bắt đầu (Finish-to-Start / FS)"},{"level":2,"text":"Bắt đầu để bắt đầu (Start-to-Start / SS)"},{"level":2,"text":"Kết thúc để kết thúc (Finish-to-Finish / FF)"},{"level":2,"text":"Bắt đầu để kết thúc (Start-to-Finish / SF)"},{"level":1,"text":"Các kỹ thuật ước lượng rất cần thiết để dự báo yêu cầu về thời gian, nguồn lực và chi phí của dự án"},{"level":2,"text":"Ước lượng từ trên xuống (Top-Down Estimating)"},{"level":2,"text":"Kỹ thuật bắt đầu bằng việc ước lượng tổng chi phí hoặc thời lượng của dự án, sau đó phân rã thành các thành phần nhỏ hơn"},{"level":2,"text":"Ước lượng từ dưới lên (Bottom-Up Estimating)"},{"level":2,"text":"Bao gồm việc ước lượng từng thành phần riêng lẻ rồi tổng hợp lại để xác định tổng chi phí hoặc thời lượng của dự án"},{"level":2,"text":"Ước lượng tương tự (Analogous Estimating)"},{"level":2,"text":"Sử dụng dữ liệu lịch sử từ các dự án tương tự trong quá khứ để ước lượng chi phí hoặc thời lượng của dự án hiện tại"},{"level":2,"text":"Ước lượng tham số (Parametric Estimating)"},{"level":2,"text":"Áp dụng mối quan hệ thống kê giữa các biến và tham số để ước lượng các đặc tính của dự án"},{"level":2,"text":"Ước lượng ba điểm (Three-Point Estimating)"},{"level":2,"text":"Xem xét các ước lượng khả dĩ nhất, lạc quan nhất và bi quan nhất để tính ước lượng trung bình có trọng số"},{"level":2,"text":"Đánh giá của chuyên gia (Expert Judgment)"},{"level":2,"text":"Dựa vào kiến thức và kinh nghiệm của các chuyên gia để ước lượng các tham số của dự án"}]},{"id":"g91","part":10,"title":"Các cột mốc (Milestones)","blocks":[{"level":1,"text":"Bước đầu tiên khi lập lịch trình dự án là phân rã các hạng mục công việc lớn này thành những phần nhỏ hơn, có thể ước lượng được"},{"level":1,"text":"Các hướng dẫn ra quyết định có thể hỗ trợ xác định mức độ chi tiết phù hợp cho bất kỳ dự án nào"},{"level":1,"text":"Các cột mốc dự án (Project Milestones)"},{"level":2,"text":"Thể hiện các điểm kiểm tra quan trọng trong một dự án, có thời lượng bằng 0 ngày và thường được biểu thị bằng hình thoi trên các lịch trình dự án dạng đồ họa"},{"level":1,"text":"Là một PM, điều quan trọng là phải đảm bảo lịch trình dự án mang tính thách thức nhưng vẫn khả thi để đội duy trì năng suất"},{"level":1,"text":"Đo lường tiến độ so với từng cột mốc giúp phát hiện sớm các vấn đề về lịch trình"},{"level":1,"text":"Các bên liên quan không tham gia vào hoạt động hằng ngày của dự án cần được cập nhật thường xuyên nhưng không cần biết về mọi quyết định nhỏ"},{"level":1,"text":"Các cột mốc dự án phổ biến"},{"level":2,"text":"Phê duyệt dự án (Project Approval)"},{"level":2,"text":"Khởi động dự án (Project Kickoff)"},{"level":2,"text":"Phê duyệt thiết kế giải pháp (Solution Design Approval)"},{"level":2,"text":"Phê duyệt lịch trình dự án (Project Schedule Approval)"},{"level":2,"text":"Chuyển đổi giai đoạn dự án (Project Phase Transition)"},{"level":2,"text":"Demo sprint (Sprint Demos)"},{"level":2,"text":"Phát hành (Release)"},{"level":2,"text":"Các sự kiện phê duyệt (Any Approval Events)"},{"level":2,"text":"Mục tiêu sprint (Sprint Goals)"},{"level":1,"text":"Trong một đội Agile, mục tiêu là tạo ra một sản phẩm có thể phát hành được sau mỗi khoảng thời gian cố định, gọi là sprint, có thể kéo dài từ 1 đến 4 tuần"},{"level":1,"text":"Để đảm bảo sự đồng bộ giữa mục tiêu sprint, các hoạt động của dự án và các cột mốc, hãy phối hợp chặt chẽ với chủ sở hữu sản phẩm (product owner) và đội phát triển trong suốt dự án"},{"level":1,"text":"Hãy xem xét các bước sau để xác định các cột mốc cho dự án của bạn"},{"level":2,"text":"Xác định các cột mốc dự án phổ biến như phê duyệt dự án, khởi động và phê duyệt lịch trình"},{"level":2,"text":"Xác định các cột mốc dự kiến cho phương pháp luận dự án của bạn"},{"level":2,"text":"Phối hợp với đội và các chuyên gia chức năng để xác định các sự kiện quan trọng đặc thù của dự án"},{"level":2,"text":"Xác định bất kỳ sự kiện phê duyệt chính thức nào"},{"level":2,"text":"Rà soát lịch trình cột mốc để đảm bảo tần suất và nhịp độ là hợp lý"},{"level":2,"text":"Điều chỉnh các cột mốc khi học được điều mới"},{"level":1,"text":"Một điểm khởi đầu tốt là có một cột mốc khoảng mỗi tháng một lần"}]});
